<?php
/** Proof — payments (spec "Proof", 3): a draft applied to two bills oldest due first; the guards' words; the approval; the record posting DR AP / CR the bank; void refused while matched, then reversed. */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
$fx = ap_fixture();
$P = mk_vendor('SMOKE Payee', ['pay_method' => 'ach']);
$Q = mk_vendor('SMOKE Other Payee');
$P1 = ready_bill($P, [['Older bill', '1', '100.00']], ['vendor_ref' => 'P-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-06-10']);
$P2 = ready_bill($P, [['Newer bill', '1', '60.00']], ['vendor_ref' => 'P-2', 'bill_date' => '2026-06-05', 'due_date' => '2026-06-20']);
$Q1 = ready_bill($Q, [['Their bill', '1', '50.00']], ['vendor_ref' => 'Q-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-06-10']);
echo "1. A draft applied oldest due first\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/payments/save.php', ['vendor' => $P, 'bank_account' => $fx['bank'], 'method' => 'ach', 'payment_date' => '2026-06-12', 'reference' => 'WIRE-1', 'bills' => [$P2, $P1]]);
$pay = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $pay > 0 && ($b['location'] ?? '') === '/payments/' . $pay . '?notice=saved' && count($b['applied'] ?? []) === 2, "payment_draft: 200, record_id $pay, two applications answered");
$row = pay_row($pay);
ok(preg_match('/^PAY-\d{6}$/', $row['number']) === 1 && $row['status'] === 'draft' && $row['amount'] === '160.00' && $row['currency'] === 'USD' && $row['method'] === 'ach' && $row['payment_date'] === '2026-06-12' && (int) $row['bank_account_id'] === $fx['bank'], 'numbered at creation; draft; the amount is the bills\' payable (160.00) when not named; USD (the bank\'s)');
$apps = q('SELECT b.vendor_ref, pa.amount FROM payment_applications pa JOIN bills b ON b.id = pa.bill_id WHERE pa.payment_id = :p ORDER BY pa.applied_at, b.due_date', ['p' => $pay]);
ok(count($apps) === 2 && array_sum(array_map('floatval', array_column($apps, 'amount'))) === 160.0, 'applied to both: 100.00 and 60.00');
$l = activity('payment.draft', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['vendor_id'] === $P && (int) $l['bank_account_id'] === $fx['bank'] && $a['amount'] === '160.00' && $a['method'] === 'ach' && count($a['applied']) === 2, 'payment.draft logs vendor_id, bank_account_id, amount, method, applied[]');
ok((int) one("SELECT count(*) FROM notifications WHERE kind = 'payment_run_awaiting' AND record_type = 'payment' AND record_id = :p", ['p' => $pay]) >= 1, 'the approvers are told (payment_run_awaiting)');
ok((string) one('SELECT status FROM bills WHERE id = :b', ['b' => $P1]) === 'approved' && (string) one('SELECT balance_due FROM bills WHERE id = :b', ['b' => $P1]) === '100.00', 'a draft payment changes no bill: still approved, 100.00 owed');
[$c, $b] = act($bea, '/payments/save.php', ['vendor' => $P, 'bank_account' => $fx['bank'], 'method' => 'ach', 'amount' => '100', 'bills' => [$P1]]);
ok($c === 422 && str_contains(msg($b), 'is owed 0.00') && str_contains(msg($b), 'would overpay it'), 'a second payment for what the first already holds: 422 "… is owed 0.00; paying … would overpay it" (' . msg($b) . ')');
ok((int) one("SELECT count(*) FROM payments WHERE vendor_id = :v AND status = 'draft'", ['v' => $P]) === 1, 'and no half-made draft is left behind');
echo "2. The guards' words\n";
[$c, $b] = act($bea, '/payments/save.php', ['vendor' => $Q, 'bank_account' => $fx['bank'], 'method' => 'ach', 'amount' => '80', 'bills' => [$Q1]]);
ok($c === 200 && ($b['applied'][0]['amount'] ?? '') === '50.00', 'a payment of 80.00 to one bill owed 50.00 applies only what the bill owes (50.00); 30.00 stays unapplied');
$big = (int) $b['record_id'];
act($bea, '/payments/delete.php', ['payment' => $big]);
$wide = mk_payment($Q, $fx['bank'], [], ['amount' => '100']);
[$c, $b] = act($bea, '/payments/apply.php', ['payment' => $wide, 'bill' => $Q1, 'amount' => '60']);
ok($c === 422 && str_contains(msg($b), 'is owed 50.00; paying 60.00 would overpay it'), 'naming 60.00 for a bill owed 50.00: 422 "… is owed 50.00; paying 60.00 would overpay it"');
act($bea, '/payments/delete.php', ['payment' => $wide]);
$qp = mk_payment($Q, $fx['bank'], [], ['amount' => '30']);
[$c, $b] = act($bea, '/payments/apply.php', ['payment' => $qp, 'bill' => $Q1, 'amount' => '40']);
ok($c === 422 && str_contains(msg($b), 'more would exceed it'), 'applying more than the payment\'s amount: 422 "… 40.00 more would exceed it"');
[$c, $b] = act($bea, '/payments/apply.php', ['payment' => $qp, 'bill' => $P1, 'amount' => '10']);
ok($c === 422 && str_contains(msg($b), 'is to another vendor than bill'), 'another vendor\'s bill: 422 "… is to another vendor …"');
$eurp = mk_payment($Q, $fx['eur'], [], ['amount' => '30']);
[$c, $b] = act($bea, '/payments/apply.php', ['payment' => $eurp, 'bill' => $Q1]);
ok($c === 422 && str_contains(msg($b), 'in different currencies'), 'a Euro payment to a dollar bill: 422 "… are in different currencies"');
act($bea, '/payments/delete.php', ['payment' => $eurp]);
[$c, $b] = act($bea, '/payments/apply.php', ['payment' => $qp, 'bill' => $Q1]);
ok($c === 200 && ($b['amount'] ?? '') === '30.00', 'apply with no amount: what fits (the 30.00 the payment has)');
[$c, $b] = act($bea, '/payments/apply.php', ['payment' => $qp, 'bill' => $Q1, 'amount' => '0']);
ok($c === 422 && isset(fields($b)['amount']), 'an amount of zero: 422 naming the field');
[$c, $b] = act($bea, '/payments/unapply.php', ['payment' => $qp, 'bill' => $Q1]);
ok($c === 200 && (string) one('SELECT count(*) FROM payment_applications WHERE payment_id = :p', ['p' => $qp]) === '0', 'unapply');
[$c, $b] = act($bea, '/payments/unapply.php', ['payment' => $qp, 'bill' => $Q1]);
ok($c === 422 && str_contains(msg($b), 'is not applied to that bill'), 'unapplying what is not applied: 422');
[$c, $b] = act($carl, '/payments/approve.php', ['payment' => $qp]);
ok($c === 422 && str_contains(msg($b), 'is not fully applied: 30.00 is unapplied — apply it or reduce the amount.'), 'approval with an unapplied amount: 422 "The payment\'s 30.00 is not fully applied: 30.00 is unapplied — apply it or reduce the amount."');
act($bea, '/payments/delete.php', ['payment' => $qp]);
echo "3. Approve\n";
[$c, $b] = act($bea, '/payments/approve.php', ['payment' => $pay]);
ok($c === 403, 'the Bookkeeper approving: 403');
[$c, $b] = act($bea, '/payments/save.php', ['payment' => $pay, 'amount' => '150']);
ok($c === 422 && str_contains(msg($b), 'already pays 160.00; unapply a bill before reducing it to 150.00.'), 'a draft\'s amount below what it pays: 422 "… already pays 160.00; unapply a bill before reducing it …"');
act($bea, '/payments/unapply.php', ['payment' => $pay, 'bill' => $P2]);
[$c, $b] = act($bea, '/payments/save.php', ['payment' => $pay, 'amount' => '100']);
ok($c === 200, 'after unapplying the 60.00 bill the amount may be reduced to 100.00');
[$c, $b] = act($bea, '/payments/save.php', ['payment' => $pay, 'amount' => '160']);
ok($c === 200, 'and raised to 160.00 again');
[$c, $b] = act($carl, '/payments/approve.php', ['payment' => $pay]);
ok($c === 422 && str_contains(msg($b), 'The payment\'s 160.00 is not fully applied: 60.00 is unapplied — apply it or reduce the amount.'), 'approval with 60.00 unapplied: 422 "The payment\'s 160.00 is not fully applied: 60.00 is unapplied — apply it or reduce the amount."');
[$c, $b] = act($bea, '/payments/apply.php', ['payment' => $pay, 'bill' => $P2]);
ok($c === 200 && ($b['amount'] ?? '') === '60.00' && (string) one('SELECT count(*) FROM payment_applications WHERE payment_id = :p', ['p' => $pay]) === '2', 'apply with no amount: the 60.00 that fits; applied to both bills again');
$since = last_activity_id();
[$c, $b] = act($carl, '/payments/approve.php', ['payment' => $pay]);
ok($c === 200 && ($b['location'] ?? '') === '/payments/' . $pay . '?notice=approved', 'payment_approve by the Controller: 200');
$row = pay_row($pay);
ok($row['status'] === 'approved' && (int) $row['approved_by'] === 28 && $row['approved_at'] !== null && $row['journal_entry_id'] === null, 'approved by 28; nothing posted yet');
$l = activity('payment.approve', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['amount'] === '160.00' && $a['currency'] === 'USD' && count($a['applied']) === 2 && (int) $l['vendor_id'] === $P, 'payment.approve logs amount, currency and applied[]');
[$c, $b] = act($bea, '/payments/save.php', ['payment' => $pay, 'amount' => '161']);
ok($c === 422 && str_contains(msg($b), 'is approved: its vendor, amount and bank account are fixed'), 'an approved payment\'s amount is fixed: 422 in the guard\'s words');
[$c, $b] = act($bea, '/payments/save.php', ['payment' => $pay, 'reference' => 'WIRE-1B', 'memo' => 'SMOKE memo']);
ok($c === 200 && (string) one('SELECT reference FROM payments WHERE id = :p', ['p' => $pay]) === 'WIRE-1B', 'its reference and memo may change');
[$c, $b] = act($carl, '/payments/approve.php', ['payment' => $pay]);
ok($c === 422 && str_contains(msg($b), 'is already approved'), 'approving twice: 422');
$draft2 = mk_payment($P, $fx['bank'], [], ['amount' => '10']);
[$c, $b] = act($carl, '/payments/approve.php', ['payment' => $draft2]);
ok($c === 422 && (str_contains(msg($b), 'is not fully applied') || str_contains(msg($b), 'applied to no bill')), 'a draft applied to no bill is not approved: 422');
echo "4. Record\n";
[$c, $b] = act($bea, '/payments/record.php', ['payment' => $draft2]);
ok($c === 422 && str_contains(msg($b), 'it must be approved before it is recorded'), 'recording before approval: 422 "… must be approved before it is recorded"');
act($bea, '/payments/delete.php', ['payment' => $draft2]);
[$c, $b] = act($vera, '/payments/record.php', ['payment' => $pay]);
ok($c === 403, 'the Viewer recording: 403');
$since = last_activity_id();
[$c, $b] = act($bea, '/payments/record.php', ['payment' => $pay, 'payment_date' => '2026-06-13']);
ok($c === 200 && ($b['location'] ?? '') === '/payments/' . $pay . '?notice=recorded' && count($b['applied'] ?? []) === 2, 'payment_record by the Bookkeeper: 200, applied[] answered');
$row = pay_row($pay);
ok($row['status'] === 'recorded' && $row['payment_date'] === '2026-06-13' && (int) $row['recorded_by'] === 27 && $row['journal_entry_id'] !== null, 'recorded on the day the money moved (2026-06-13) by 27; posted');
$jl = array_column(q('SELECT a.code, l.debit, l.credit, l.vendor_id FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e', ['e' => $row['journal_entry_id']]), null, 'code');
ok(count($jl) === 2 && $jl['2000']['debit'] === '160.00' && (int) $jl['2000']['vendor_id'] === $P && $jl['1010']['credit'] === '160.00', 'the entry: DR 2000 (the vendor) 160.00 / CR 1010 160.00');
$x1 = bill_row($P1); $x2 = bill_row($P2);
ok($x1['status'] === 'paid' && $x1['amount_paid'] === '100.00' && $x1['balance_due'] === '0.00' && $x1['paid_at'] !== null && $x2['status'] === 'paid' && $x2['amount_paid'] === '60.00', 'both bills are paid, with paid_at');
$l = activity('payment.record', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['vendor_id'] === $P && (int) $l['bank_account_id'] === $fx['bank'] && (int) $l['journal_entry_id'] === (int) $row['journal_entry_id'] && $a['number'] === $row['number'] && $a['amount'] === '160.00' && $a['method'] === 'ach' && $a['bank_account_id'] === $fx['bank'] && count($a['applied']) === 2, 'payment.record logs number, amount, method, bank_account_id, applied[], vendor_id, journal_entry_id');
[$c, $b] = act($bea, '/payments/record.php', ['payment' => $pay]);
ok($c === 422 && str_contains(msg($b), 'must be approved before it is recorded'), 'recording twice: 422');
[$c, $b] = act($bea, '/payments/unapply.php', ['payment' => $pay, 'bill' => $P1]);
ok($c === 422 && str_contains(msg($b), 'its applications are fixed'), 'a recorded payment\'s applications are fixed');
[$c, $b] = act($carl, '/bills/void.php', ['bill' => $P1, 'reason' => 'x']);
ok($c === 422 && str_contains(msg($b), 'has payments or credits applied; unapply them first'), 'a paid bill cannot be voided (guard)');
$body = page($bea, '/payments/' . $pay . '?notice=recorded')['body'];
ok(str_contains($body, 'Recorded as paid — match it when it shows at the bank') && str_contains($body, 'href="/cash/match?bank_account=' . $fx['bank'] . '"'), 'the page says "match it when it shows at the bank" with a link to /cash/match?bank_account=');
echo "5. Cheques\n";
$C1 = ready_bill($Q, [['Cheque bill', '1', '40.00']], ['vendor_ref' => 'Q-CHQ', 'bill_date' => '2026-06-01', 'due_date' => '2026-06-30']);
$ck = mk_payment($Q, $fx['bank'], [$C1], ['method' => 'cheque']);
act($carl, '/payments/approve.php', ['payment' => $ck]);
[$c, $b] = act($bea, '/payments/record.php', ['payment' => $ck]);
ok($c === 422 && str_contains(msg($b), 'is a cheque: give its cheque number'), 'a cheque without its number is not recorded: 422');
[$c, $b] = act($bea, '/payments/record.php', ['payment' => $ck, 'cheque_number' => '2001', 'reference' => 'CHQ 2001']);
ok($c === 200 && (string) one('SELECT cheque_number FROM payments WHERE id = :p', ['p' => $ck]) === '2001' && (string) one('SELECT reference FROM payments WHERE id = :p', ['p' => $ck]) === 'CHQ 2001', 'with the number given at record time it goes through');
echo "6. Void\n";
[$c, $b] = act($bea, '/payments/void.php', ['payment' => $ck, 'reason' => 'x']);
ok($c === 403, 'a Bookkeeper voiding: 403');
[$c, $b] = act($carl, '/payments/void.php', ['payment' => $ck, 'reason' => '']);
ok($c === 422 && str_contains(msg($b), 'Voiding a payment needs a reason'), 'no reason: 422');
$line = (int) one("INSERT INTO bank_transactions (bank_account_id, txn_date, amount, description, status, matched_type, matched_id, matched_by, matched_at) VALUES (:b, '2026-06-14', -40.00, 'SMOKE CHQ 2001', 'matched', 'payment', :p, 28, now()) RETURNING id", ['b' => $fx['bank'], 'p' => $ck]);
$body = page($bea, '/payments/' . $ck)['body'];
ok(str_contains($body, 'id="payment-head-matched"'), 'the page shows the bank line it matched (slice 6\'s fixture row)');
[$c, $b] = act($carl, '/payments/void.php', ['payment' => $ck, 'reason' => 'SMOKE x']);
ok($c === 422 && str_contains(msg($b), 'is matched to a bank line; unmatch it first'), 'void refused while matched: "… is matched to a bank line; unmatch it first"');
q("UPDATE bank_transactions SET status = 'unmatched', matched_type = NULL, matched_id = NULL WHERE id = :l", ['l' => $line]); q('DELETE FROM bank_transactions WHERE id = :l', ['l' => $line]);
$since = last_activity_id();
[$c, $b] = act($carl, '/payments/void.php', ['payment' => $ck, 'reason' => 'SMOKE cheque lost']);
$r = pay_row($ck);
ok($c === 200 && $r['status'] === 'void' && $r['void_reason'] === 'SMOKE cheque lost' && (int) one('SELECT count(*) FROM journal_entries WHERE reversal_of = :e', ['e' => $r['journal_entry_id']]) === 1, 'void: reversed, reason kept');
$x = bill_row($C1);
ok($x['status'] === 'approved' && $x['amount_paid'] === '0.00' && $x['balance_due'] === '40.00', 'the bill is owed again (approved, 40.00)');
$l = activity('payment.void', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['reason'] === 'SMOKE cheque lost' && $a['amount'] === '40.00' && (int) $l['journal_entry_id'] === (int) $r['journal_entry_id'], 'payment.void logs reason and amount');
[$c, $b] = act($carl, '/payments/void.php', ['payment' => $ck, 'reason' => 'again']);
ok($c === 422, 'a void payment cannot be voided again');
echo "7. Draft delete\n";
$d3 = mk_payment($Q, $fx['bank'], [$C1], ['method' => 'cash']);
$since = last_activity_id();
[$c, $b] = act($bea, '/payments/delete.php', ['payment' => $d3]);
ok($c === 200 && one('SELECT 1 FROM payments WHERE id = :p', ['p' => $d3]) === false && (int) one('SELECT count(*) FROM payment_applications WHERE payment_id = :p', ['p' => $d3]) === 0 && count(activity('payment.delete', $since)) === 1, 'payment_delete removes a draft and its applications; payment.delete logged');
[$c, $b] = act($bea, '/payments/delete.php', ['payment' => $pay]);
ok($c === 422 && str_contains(msg($b), 'is recorded and is never deleted; void it'), 'a recorded payment is never deleted');
echo "8. The pages\n";
$body = page($bea, '/payments/new?vendor=' . $Q . '&bill=' . $C1)['body'];
ok(str_contains($body, 'id="payment-form"') && str_contains($body, 'id="payment-bill-' . $C1 . '"') && str_contains($body, 'checked') && str_contains($body, 'value="40.00"') && str_contains($body, 'id="payment-form-field-bank"'), 'the form with ?bill=: the bill checked, the amount prefilled 40.00, the bank account select');
$body = page($bea, '/payments/new')['body'];
ok(str_contains($body, 'id="payment-vendor-form"') && str_contains($body, 'Who is being paid?'), 'without a vendor: the first step asks who is being paid');
$d = screen($bea, '/payments/new?vendor=' . $Q)[1];
ok(($d['vendor']['vendor_id'] ?? 0) === $Q && count($d['payable_bills'] ?? []) >= 1 && isset($d['payable_bills'][0]['payable']), 'JSON: the vendor\'s payable bills with what is payable');
$body = page($bea, '/payments/')['body'];
ok(str_contains($body, 'id="payments-tab-draft"') && str_contains($body, 'id="payments-tab-approved"') && str_contains($body, 'id="payments-tab-recorded"') && str_contains($body, 'id="payment-row-' . $pay . '"') && str_contains($body, 'id="payment-card-' . $pay . '"'), 'the list: tabs Draft, Approved, Recorded; a row and a card');
$d = screen($bea, '/payments/?status=recorded')[1];
ok(array_unique(array_column($d['payments'] ?? [], 'status')) === ['recorded'] && in_array($pay, array_column($d['payments'], 'payment_id'), true), 'status=recorded lists recorded payments');
$d = screen($bea, '/payments/?vendor=' . $Q . '&bank_account=' . $fx['bank'])[1];
ok(count(array_filter($d['payments'], fn ($x) => $x['vendor']['vendor_id'] !== $Q)) === 0, 'vendor and bank account filter');
$d = screen($bea, '/payments/' . $pay)[1];
ok(($d['payment']['number'] ?? '') === $row['number'] && count($d['payment']['applications'] ?? []) === 2 && ($d['payment']['journal_entry']['number'] ?? '') !== '' && isset($d['timeline'], $d['may']), 'JSON: the payment with applications, entry and timeline');
$body = page($vera, '/payments/' . $pay)['body'];
ok(!str_contains($body, 'id="payment-actions"'), 'a Viewer sees the payment without actions');
finish();
